COMMENT ON COLUMN mcc_code.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN mcc_code.created_at IS 'Creation time';
COMMENT ON COLUMN mcc_code.created_by IS 'Principal that created the row';
COMMENT ON COLUMN mcc_code.updated_at IS 'Last update time';
COMMENT ON COLUMN mcc_code.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN mcc_code.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN mcc_code.code IS 'MCC';
COMMENT ON COLUMN mcc_code.description IS 'Description';
COMMENT ON COLUMN mcc_code.category IS 'Category group';
COMMENT ON COLUMN mcc_code.is_high_risk IS 'High-risk category (gambling, crypto ...)';
COMMENT ON COLUMN mcc_code.is_quasi_cash IS 'Quasi-cash';
COMMENT ON COLUMN mcc_code.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN mcc_code.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN mcc_code.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN mcc_code.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN mcc_code.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE TRIGGER trg_mcc_code_touch BEFORE UPDATE ON mcc_code FOR EACH ROW EXECUTE FUNCTION touch_row();

-- purpose_code: ISO 20022 external purpose code for payments
CREATE TABLE purpose_code (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  code                         varchar(4) NOT NULL,
  name                         varchar(160) NOT NULL,
  category                     varchar(80),
  description                  varchar(500),
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_purpose_code_code UNIQUE (code)
);
COMMENT ON TABLE purpose_code IS 'ISO 20022 external purpose code for payments';
COMMENT ON COLUMN purpose_code.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN purpose_code.created_at IS 'Creation time';
COMMENT ON COLUMN purpose_code.created_by IS 'Principal that created the row';
COMMENT ON COLUMN purpose_code.updated_at IS 'Last update time';
COMMENT ON COLUMN purpose_code.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN purpose_code.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN purpose_code.code IS 'ISO 20022 purpose code, e.g. SALA';
COMMENT ON COLUMN purpose_code.name IS 'Name';
COMMENT ON COLUMN purpose_code.category IS 'Category';
COMMENT ON COLUMN purpose_code.description IS 'Definition';
COMMENT ON COLUMN purpose_code.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN purpose_code.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN purpose_code.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN purpose_code.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN purpose_code.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE TRIGGER trg_purpose_code_touch BEFORE UPDATE ON purpose_code FOR EACH ROW EXECUTE FUNCTION touch_row();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA refdata TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA refdata TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA refdata GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
